const r = await tools.mcp__codex_apps__lobu_query_sdk({timeout_ms:60000,script:`export default async (_ctx, client) => {
  const result = await client.operations.listRuns({
    connection_ids: [403, 408, 410, 412, 480, 494, 495],
    run_types: ["sync"],
    limit: 500
  });
  const runs = result?.items ?? result?.runs ?? [];
  const byFeed = new Map();
  for (const run of runs) {
    const key = String(run.feed_id ?? "none");
    const row = byFeed.get(key) ?? {
      feed_id: run.feed_id ?? null,
      connector_key: run.connector_key ?? null,
      total_runs: 0,
      completed_runs: 0,
      failed_runs: 0,
      max_items_collected: 0,
      sum_completed_items: 0,
      latest_created_at: null,
      latest_status: null,
      latest_error: null
    };
    row.total_runs += 1;
    if (run.status === "completed") {
      row.completed_runs += 1;
      const n = Number(run.items_collected ?? 0);
      row.max_items_collected = Math.max(row.max_items_collected, n);
      row.sum_completed_items += n;
    }
    if (run.status === "failed") row.failed_runs += 1;
    if (!row.latest_created_at || String(run.created_at) > row.latest_created_at) {
      row.latest_created_at = run.created_at;
      row.latest_status = run.status;
      row.latest_error = run.error_message ?? null;
    }
    byFeed.set(key, row);
  }
  return { total: runs.length, feeds: [...byFeed.values()].sort((a,b) => Number(a.feed_id)-Number(b.feed_id)) };
}`});
text(JSON.stringify(r.structuredContent ?? r, null, 2));

